import sys


def main():
    flags = []
    filepath = None

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg.startswith("-") and not arg.startswith("--"):
            for ch in arg[1:]:
                if ch in ("l", "w", "c"):
                    flags.append(ch)
                else:
                    print(f"Unknown option: {arg}", file=sys.stderr)
                    sys.exit(1)
        elif filepath is None:
            filepath = arg
        else:
            print("Too many arguments", file=sys.stderr)
            sys.exit(1)
        i += 1

    # Default to all three if no flags given
    if not flags:
        flags = ["l", "w", "c"]

    # Fixed output order: lines, words, characters
    show_lines = "l" in flags
    show_words = "w" in flags
    show_chars = "c" in flags

    # Determine input source
    if filepath is None or filepath == "-":
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, "rb") as f:
            data = f.read()

    # Count characters (bytes)
    num_chars = len(data)

    # Count lines: split on newlines; a final line with no trailing newline still counts
    lines = data.split(b"\n")
    # If data ends with \n, the last element after split is empty bytes — don't count it
    if data.endswith(b"\n") and len(lines) > 0 and lines[-1] == b"":
        num_lines = len(lines) - 1
    else:
        num_lines = len(lines) - 1 if len(lines) > 0 else 0
        # Actually: splitting "a\nb\n" gives [b"a", b"b", b""], so 3 elements, 2 real lines.
        # Splitting "a\nb" gives [b"a", b"b"], so 2 elements, 2 real lines.
        # Splitting "" gives [b""], so 1 element, 0 lines.
        if len(lines) == 1 and lines[0] == b"":
            num_lines = 0
        else:
            num_lines = len(lines) - 1

    # Count words: whitespace-separated tokens in the decoded text
    num_words = len(data.decode("utf-8").split())

    # Build output
    parts = []
    if show_lines:
        parts.append(str(num_lines))
    if show_words:
        parts.append(str(num_words))
    if show_chars:
        parts.append(str(num_chars))

    print(" ".join(parts))


if __name__ == "__main__":
    main()
